        status, retired = simulate_one()
        for d in DRIVERS:
            s = status.get(d)
            if s == "dns":
                dns_counts[d] += 1
            elif s == "dsq":
                dsq_counts[d] += 1
            elif s == "nc":
                nc_counts[d] += 1
            elif isinstance(s, int):
                pos_counts[d][s - 1] += 1
            else:
                dns_counts[d] += 1
            if retired[d]:
                ret_counts[d] += 1

    n = float(N_SIMS)
    raw = {}
    for d in DRIVERS:
        raw[d] = {
            "positions": [pos_counts[d][i] / n for i in range(22)],
            "nc": nc_counts[d] / n,
            "dns": dns_counts[d] / n,
            "dsq": dsq_counts[d] / n,
            "retirement": ret_counts[d] / n,
        }

    print("=== WIN PROBS ===")
    wins = sorted(((raw[d]["positions"][0], d) for d in DRIVERS), reverse=True)
    for p, d in wins[:12]:
        print(f"  {d}: {p:.4f}")
    print("=== PODIUM ===")
    pods = sorted(((sum(raw[d]["positions"][:3]), d) for d in DRIVERS), reverse=True)
    for p, d in pods[:12]:
        print(f"  {d}: {p:.4f}")
    print("=== TOP10 ===")
    t10 = sorted(((sum(raw[d]["positions"][:10]), d) for d in DRIVERS), reverse=True)
    for p, d in t10:
        print(f"  {d}: t10={p:.3f}  p1={raw[d]['positions'][0]:.3f}  meanpos~ "
              f"{sum((i+1)*raw[d]['positions'][i] for i in range(22))/(sum(raw[d]['positions'])+1e-9):.1f}  "
              f"ret={raw[d]['retirement']:.3f} nc={raw[d]['nc']:.3f} dns={raw[d]['dns']:.3f}")
    print("=== OCCUPANCY ===")
    for i in range(22):
        s = sum(raw[d]["positions"][i] for d in DRIVERS)
        print(f"  P{i+1}: {s:.4f}")
    print("mean classified", sum(sum(raw[d]["positions"]) for d in DRIVERS))

    with open("/workspace/raw_probs.json", "w") as f:
        json.dump(raw, f)
    print("saved")


if __name__ == "__main__":
    main()
